pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(this));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(sender);
        bool ok;
        try c.sendTo(address(0xdead), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false || address(c).balance == balanceBefore);
    }
}
